export const DICTS: Record<Lang, Dict> = { en, ru, ky };
export const getDict = (l: string): Dict => DICTS[(l as Lang)] ?? en;
export const isLang = (l: string): l is Lang => l in DICTS;

/** Replaces {key} placeholders. Unknown keys are left visible so missing data is noticed in QA. */
export function fmt(s: string, v: Record<string, string | number> = {}): string {
  return s.replace(/\{(\w+)\}/g, (m, k) => (k in v ? String(v[k]) : m));
}
/** Translates an API error body ({ code }) into the user's language. */
/** Translates curated destination facts (tags, region, season, duration, difficulty). Unknown values pass through. */
export function fact(t: Dict, kind: keyof Dict['facts'], value: string | null | undefined): string {
  if (!value) return '';
  return (t.facts[kind] as Record<string, string>)[value] ?? value;
}
export function errorText(t: Dict, body: { code?: string; error?: string } | null | undefined): string {
  const c = body?.code as keyof Dict['errors'] | undefined;
  return (c && t.errors[c]) || t.errors.generic;
}
